#define SKILL           0x280e4UL
#define SHOTS           0x28356UL
#define CELL_TERRAIN    0x283caUL
#define SKILL_KINDS     0xba88u
#define TERRAIN_COVER   0x3e56u
#define TEMPLATE_TABLES 0x32d4u
#define TERRAIN_EXTRAS  0x3dbeu
#define HOUR            0x47u
