/* 0548: casualties of one ranged shot. A missing target or one standing on
 * an occupied terrain extra (a bunker) sets the flag and takes a fixed
 * square-root barrage; otherwise a hit scales by power, defense, cover,
 * weather and night. The shooter's unit spends a third of its shots. */
uint16_t opeu_battle_ranged_damage(uint8_t* ds, BattleEvent event,
                                   uint16_t shooter, uint16_t target,
                                   uint16_t bunker) {
  uint16_t type, count, unit, ammo, shots, power, defense, grade, size, p, f,
      spread, base, r;
  uint16_t j, extra, pos;
  if (!target)
    set_word(ds, bunker, 1);
  else {
    set_word(ds, bunker, 0);
    pos = word_at(ds, (uint16_t)(target + 7));
    for (j = 0; j < 10; j++) {
      extra = (uint16_t)(TERRAIN_EXTRAS + j * 3u);
      if (ds[extra] == 0xff)
        break;
      if (ds[pos] == ds[extra] &&
          ds[(uint16_t)(pos + 1)] == ds[(uint16_t)(extra + 1)] &&
          ds[(uint16_t)(extra + 2)]) {
        set_word(ds, bunker, 1);
        break;
      }
    }
  }
  unit  = opeu_battle_element_unit(ds, event, shooter);
  shots = (uint8_t)call2(ds, event, SHOTS, target, shooter) / 3u;
  ammo  = word_at(ds, (uint16_t)(unit + 6));
  set_word(ds, (uint16_t)(unit + 6),
           (uint16_t)(ammo - (ammo < shots ? ammo : shots)));
  type  = TYPE(shooter);
  count = word_at(ds, (uint16_t)(shooter + 3));
  if (ds[(uint16_t)(type + 4)] == 0)
    count /= 10;
  if (word_at(ds, bunker))
    return (uint16_t)(MUL16(call1(ds, event, ISQRT, ds[(uint16_t)(type + 5)]),
                            count) /
                      100);
  if (!opeu_battle_ranged_hits(ds, event, shooter, target))
    return 0;
  power   = opeu_battle_ranged_power(ds, event, shooter, target);
  defense = opeu_battle_ranged_defense(ds, event, target);
  grade   = rand_bounded(ds, event, 2);
  grade   = (uint16_t)(grade + MUL16(power, 10) / opeu_max16(defense, 1));
  count   = (uint16_t)(count / 10 + 1);
  type    = TYPE(target);
  size    = word_at(ds, (uint16_t)(target + 3));
  size =
      (uint16_t)((ds[(uint16_t)(type + 4)] == 0 ? size / 100 : size / 10) + 1);
  p      = cover(ds, event, target, &f);
  spread = opeu_max16((uint16_t)(p / 5 + f / 3 + 2), 1);
  if (ds[(uint16_t)(type + 4)] == 7 || ds[(uint16_t)(type + 4)] == 6 ||
      (ds[(uint16_t)(type + 4)] == 4 && (ds[(uint16_t)(type + 12)] & 8))) {
    base =
        (uint16_t)(MUL16(grade / 10, count) / 7 / (night(ds) ? 2 : 1) / spread);
    r = rand_bounded(ds, event, 2);
    return (uint16_t)(r + MUL16(rand_bounded(ds, event, 6) == 0 ? 2 : 1, base));
  }
  base = MUL16(MUL16(grade, count) / (night(ds) ? 2 : 1) / spread, size);
  r    = rand_bounded(ds, event, 2);
  return (uint16_t)(r + MUL16(base / (ds[(uint16_t)(type + 4)] == 0 ? 7 : 70),
                              rand_bounded(ds, event, 6) == 0 ? 2 : 1));
}
